function refreshReportPreview(){const rows=reportRows(),count=$('#reportCount'),box=$('#reportPreview');if(count)count.textContent=String(rows.length);if(!box)return;if(!rows.length){box.innerHTML=empty(t('noData'));return}box.innerHTML=`<div class="table-wrap"><table class="data-table preview-table"><thead><tr>${[t('name'),t('class'),t('club')+'/'+t('activity'),t('status'),t('submitted')].map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,8).map(r=>`<tr><td>${e(r.name)}</td><td>${e(r.className)}</td><td>${e(r.targetName||'—')}</td><td>${e(t(r.kind==='activity'?(r.participationStatus||r.status):r.status))}</td><td>${fmtDate(r.created)}</td></tr>`).join('')}</tbody></table></div>${rows.length>8?`<small class="form-note">+ ${rows.length-8} ${t('allRequests')}</small>`:''}`}function reportRows(){let kind=$('#reportKind')?.value||'all',target=$('#reportTarget')?.value||'all',status=$('#reportStatus')?.value||'all',from=$('#reportFrom')?.value||'',to=$('#reportTo')?.value||'';return db.requests.filter(r=>{let rs=r.kind==='activity'?(r.participationStatus||r.status):r.status;return(kind==='all'||r.kind===kind)&&(target==='all'||r.targetId===target)&&(status==='all'||rs===status||(status==='pending'&&r.kind==='activity'&&r.status==='pending'))&&(from===''||r.created>=from)&&(to===''||r.created<=to)}).sort((a,b)=>a.created.localeCompare(b.created))}function reportHeaders(){return [t('name'),t('class'),t('type'),t('club')+'/'+t('activity'),t('status'),t('role'),t('submitted'),t('generated')]}function reportData(r){return [r.name,r.className,r.kind==='club'?t('club'):t('activity'),r.targetName,r.kind==='activity'?t(r.participationStatus||r.status):t(r.status),t(r.role||'student'),r.created,t('schoolYear')]}
function exportCSV(){const rows=reportRows();if(!rows.length){toast(t('noData'));return}const data=[reportHeaders(),...rows.map(reportData)],csv='\ufeff'+data.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),`school-report-${today()}.csv`)}function exportWord(){const rows=reportRows();if(!rows.length){toast(t('noData'));return}let html=`<!doctype html><html lang="${lang}" dir="${lang==='ar'?'rtl':'ltr'}"><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;color:#192746}h1{text-align:center;color:#122448}table{width:100%;border-collapse:collapse}th,td{border:1px solid #9aa5b7;padding:8px;text-align:start}th{background:#e7f4f2}.meta{text-align:center;color:#667}</style></head><body><h1>${t('reportTitle')} — ${t('schoolYear')}</h1><p>${t('generated')}: ${fmtDate(today())}</p><table><thead><tr>${reportHeaders().map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${reportData(r).map(x=>`<td>${e(x)}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="meta">${t('schoolName')} · School Hub</p></body></html>`;download(new Blob(['\ufeff',html],{type:'application/msword;charset=utf-8'}),`school-report-${today()}.doc`)}function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

