async function cloudUpsert(table,row){if(!backendConfigured)return true;if(!supabaseClient){toast(t('cloudError'));return false}if(!admin&&!coordinator){toast(t('adminRequired'));return false}const {error}=await supabaseClient.from(table).upsert(row,{onConflict:'id'});if(error){console.error(error);toast(backendError(error));return false}return true}
