async function saveSharedContent(type,item){const arr=CONTENT_ARRAY[type];if(!arr)return false;if(backendConfigured){if(!admin&&!coordinator){toast(t('adminRequired'));return false}const permitted=type==='club'?canManageClub(item.id):type==='activity'?canManageClub(item.clubId):type==='media'?item.scopeType==='general'?admin:item.scopeType==='club'?canManageClub(item.scopeId):canManageActivity(item.scopeId):admin;if(!permitted){toast(t('onlyAssignedClubs'));return false}if(!(await cloudUpsert('school_content',{id:item.id,content_type:type,payload:item,updated_at:new Date().toISOString()})))return false}db[arr]=mergeById(db[arr]||[],[item]);save();return true}
async function loadSharedContent(){if(!supabaseClient)return false;const {data,error}=await supabaseClient.from('school_content').select('id,content_type,payload').order('updated_at',{ascending:true});if(error){console.error('school_content load failed',error);return false}const grouped={news:[],club:[],activity:[],media:[]};for(const row of data||[])if(grouped[row.content_type]&&row.payload)grouped[row.content_type].push(row.payload);for(const [type,arr] of Object.entries(CONTENT_ARRAY))db[arr]=mergeById(db[arr]||[],grouped[type]);save();return true}
async function ensureCoordinatorContent(){if(!supabaseClient||!coordinator||!managedClubIds.length)return;const records=[...db.clubs.filter(c=>managedClubIds.includes(String(c.id))).map(x=>({type:'club',item:x})),...db.activities.filter(a=>managedClubIds.includes(String(a.clubId))).map(x=>({type:'activity',item:x}))];if(!records.length)return;const ids=records.map(x=>x.item.id);const {data,error}=await supabaseClient.from('school_content').select('id').in('id',ids);if(error){console.error(error);return}const existing=new Set((data||[]).map(x=>x.id));for(const row of records){if(existing.has(row.item.id))continue;const {error:insertError}=await supabaseClient.from('school_content').insert({id:row.item.id,content_type:row.type,payload:row.item,updated_at:new Date().toISOString()});if(insertError&&insertError.code!=='23505')console.error(insertError)}await loadSharedContent()}
