async function checkAdminSession(){if(!supabaseClient)return false;const {data:{user}}=await supabaseClient.auth.getUser();if(!user){admin=false;coordinator=false;managedClubIds=[];cloudUser=null;return false}const {data:roleRow,error}=await supabaseClient.from('user_roles').select('role').eq('user_id',user.id).maybeSingle();if(error||!['admin','club_coordinator'].includes(roleRow?.role)){await supabaseClient.auth.signOut();admin=false;coordinator=false;managedClubIds=[];cloudUser=null;return false}cloudUser=user;admin=roleRow.role==='admin';coordinator=roleRow.role==='club_coordinator';managedClubIds=[];if(coordinator){const {data:assigned,error:assignmentError}=await supabaseClient.from('user_club_assignments').select('club_id').eq('user_id',user.id);if(assignmentError){console.error(assignmentError);managedClubIds=[]}else managedClubIds=(assigned||[]).map(x=>String(x.club_id))}return true}
async function loadAdminData(){if(!supabaseClient||!admin)return;await loadSharedContent();const [rq,pr,lg]=await Promise.all([supabaseClient.from('applications').select('*').order('created_at',{ascending:false}),supabaseClient.from('school_projects').select('id,code,payload'),supabaseClient.from('activity_logs').select('id,project_id,activity_date,payload').order('activity_date',{ascending:false})]);if(rq.error){toast(t('cloudError'));return}db.requests=(rq.data||[]).map(x=>({id:x.id,kind:x.kind,targetId:x.target_id,targetName:x.target_name,name:x.full_name,className:x.class_name,reason:x.reason,role:x.participation_type,status:x.status,participationStatus:x.participation_status,created:String(x.created_at).slice(0,10)}));if(!pr.error){const remote=(pr.data||[]).map(x=>x.payload).filter(Boolean),ids=new Set(remote.map(x=>x.id));db.projects=[...remote,...(db.projects||[]).filter(x=>!ids.has(x.id))]}if(!lg.error){const remote=(lg.data||[]).map(x=>x.payload).filter(Boolean),ids=new Set(remote.map(x=>x.id));db.logs=[...remote,...(db.logs||[]).filter(x=>!ids.has(x.id))]}save()}
